        gates.append(('AND', term))
    or_gate = ('OR', gates)
    return or_gate

def build_xor_tree(n):
    if n == 1:
        return ('input', 0)
    left = build_xor_tree(n // 2)
    right = build_xor_tree((n + 1) // 2)
    return ('XOR', [left, right])

def demorgan_expand(gate):
    op, children = gate
    if op == 'XOR':
        a, b = children
        a_not = ('NOT', [a])
        b_not = ('NOT', [b])
        and1 = ('AND', [a, b_not])
        and2 = ('AND', [a_not, b])
        return ('OR', [and1, and2])
    elif op == 'NOT':
        child = children[0]
        if child[0] == 'AND':
            new_children = [('NOT', [c]) for c in child[1]]
            return ('OR', new_children)
        elif child[0] == 'OR':
            new_children = [('NOT', [c]) for c in child[1]]
            return ('AND', new_children)
        elif child[0] == 'NOT':
